import {chapterFrame,storyOpening,aiPage} from './external-journey-frame.js?v=20260922-agent1';
import {vendorConfig} from './vendor-config.js?v=20260921-portals1';
import {cases} from './workshop.js?v=20260925-clientcases1';

const e=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let view='experience';
let stageIndex=0;
const checked=new Set();

const stages=[
  ['Discover','Evan finds the Harborline Integration Exchange through a branded partner invitation.','The application explains the relationship, requested data and support boundary before sign-up.'],
  ['Register','He creates an External ID account in the customer tenant.','The user flow collects only the profile attributes needed to begin partner verification.'],
  ['Verify','Harborline connects Evan to Tidewater’s approved integration agreement.','Trusted business context comes from the partner registry, not from a company name typed during registration.'],
  ['Register app','Evan registers an integration after signing in.','The Exchange records the integration and its approved API products under the verified partner relationship.'],
  ['Issue credential','The Exchange creates the application identity and shows its client secret once.','Keep the secret private. Show the client ID and the approved sandbox permission, never the secret itself.'],
  ['Get token','The registered integration obtains an app-only token with client credentials.','The token identifies the application, not Evan. Validate its issuer, audience, expiry and granted application permission.'],
  ['Call API','Use the token for one allowed sandbox call and one denied production action.','The resource API enforces the current integration permission and partner boundary for each request.'],
  ['Expire','The engagement ends and partner access closes without creating an employee offboarding task.','The application revokes credentials and relationships, then retains evidence of the completed boundary.']
];

const proof=[
  ['Correct external tenant','External tenant','Show the application, associated sign-up/sign-in user flow and Evan’s customer record.'],
  ['Trusted partner mapping','Partner registry','Show Evan’s stable subject linked to Tidewater Channel Systems, the sponsor and effective dates.'],
  ['Registered integration','Integration Exchange','Show the integration app/client ID and approved sandbox API permission. Keep the one-time secret private.'],
  ['App token + API boundary','Exchange + Resource API','Show the app-only token metadata, one allowed sandbox call and one denied production action; record actual responses.'],
  ['One correlation trail','Sign-in + app + API logs','Keep Evan’s user subject distinct from the integration app ID; correlate registration, token, request, time and result.'],
  ['Restored baseline','Tenant + application','Remove the prepared change, revoke the test session and prove the denial still holds.']
];

function journey(){return `<div class="vendor-journey partner-journey" aria-label="Evan’s External ID lifecycle"><span>EXTERNAL ID JOURNEY</span>${stages.map((stage,index)=>`<button data-partner="stage" data-index="${index}" class="${index===stageIndex?'active':''}" aria-pressed="${index===stageIndex}"><b>0${index+1}</b><small>${e(stage[0])}</small></button>`).join('')}</div>`;}

function workspace(){return `<section class="partner-workspace"><div class="partner-story"><span class="vendor-kicker">ILLUSTRATIVE WORKSHOP PREVIEW</span><h2>A developer joins the ecosystem.<br><em>He never becomes an employee.</em></h2><p>Evan works for Tidewater Channel Systems, an approved integration partner. He signs in through Harborline’s branded External ID flow and is matched to a verified agreement. He registers a separate integration; it receives a client ID, a one-time secret and only the approved sandbox API permission. The integration exchanges its credentials for an app-only token. Publishing production access requires a separate approval. When the engagement ends, Harborline removes the partner relationship and credentials while preserving the identity and application evidence needed for audit.</p><div class="partner-principle"><b>IDENTITY</b><span>Who is Evan?</span><b>RELATIONSHIP</b><span>Does he represent Tidewater Channel Systems?</span><b>AUTHORIZATION</b><span>Which API action is allowed now?</span></div></div><aside class="partner-console"><header><span>HARBORLINE</span><small>INTEGRATION EXCHANGE</small></header><div class="partner-console-user"><i>ET</i><div><strong>Evan Torres</strong><span>Tidewater Channel Systems · Integration developer</span></div><em>EXTERNAL</em></div><div class="partner-console-grid"><div><small>ENVIRONMENT</small><strong>Sandbox</strong><span>Ready</span></div><div><small>API SCOPE</small><strong>reservations.read</strong><span>Approved</span></div><div><small>PRODUCTION</small><strong>Credential publish</strong><span>Step-up required</span></div><div><small>AGREEMENT</small><strong>31 Dec 2026</strong><span>Time-bound</span></div></div><div class="partner-api"><span>GET /v1/reservations/preview</span><b>200 · ALLOW</b></div><div class="partner-api denied"><span>POST /v1/properties/harbor-view</span><b>403 · DENY</b></div><div class="partner-live-actions"><a href="${e(vendorConfig.integrationPortalUrl)}" target="_blank" rel="noopener noreferrer">Open live Integration Exchange ↗</a><small>PORTAL LINK AVAILABLE · OUTCOMES BELOW ARE ILLUSTRATIVE</small></div></aside></section>`;}

function architecture(){return `<section class="partner-decision-architecture"><header><div><span class="vendor-kicker">EVAN’S REQUEST · WHO DECIDES WHAT?</span><h2>Four decisions turn a sign-in into a safe API call.</h2><p>Use this view while the tenant and Integration Exchange are open. Each card names the owner, the decision and the exact proof to show.</p></div><span>LIVE DEMO MAP</span></header><div class="partner-decision-flow"><article><b>01</b><span>IDENTITY</span><h3>Microsoft Entra External ID</h3><strong>Is this Evan?</strong><p>User flow authenticates him and issues a stable subject.</p><em>SHOW · customer record + sign-in event</em></article><i>subject</i><article><b>02</b><span>BUSINESS TRUST</span><h3>Partner registry</h3><strong>Does he represent Tidewater Channel Systems?</strong><p>Sponsor, agreement and dates establish the relationship.</p><em>SHOW · subject → company mapping</em></article><i>partner</i><article><b>03</b><span>TECHNICAL SCOPE</span><h3>Token validation</h3><strong>Is this token valid here?</strong><p>Issuer, audience, expiry and scope form the API contract.</p><em>SHOW · aud + reservations.read</em></article><i>request</i><article class="decision"><b>04</b><span>ENFORCEMENT</span><h3>Resource API</h3><strong>May he do this now?</strong><p>The API combines token and current partner authorization.</p><em>SHOW · 200 ALLOW + 403 DENY</em></article></div><div class="partner-request-trace"><span>REQUEST UNDER TEST</span><div><b>SUBJECT</b><strong>Evan’s stable External ID subject</strong></div><div><b>PARTNER</b><strong>Tidewater Channel Systems · agreement active</strong></div><div><b>SCOPE</b><strong>reservations.read</strong></div><div><b>RESOURCE</b><strong>Sandbox reservations</strong></div><div class="allow"><b>DECISION</b><strong>200 · ALLOW</strong></div></div><div class="partner-ownership"><div><span>SYSTEM</span><span>OWNS</span><span>VERIFY LIVE</span></div><div><strong>External tenant</strong><p>Authentication and stable subject</p><em>Application, user flow, customer record, sign-in</em></div><div><strong>Partner registry</strong><p>Company relationship and effective dates</p><em>Tidewater Channel Systems mapping, sponsor, agreement status</em></div><div><strong>Integration Exchange</strong><p>Consent and developer experience</p><em>Sandbox workspace and requested scope</em></div><div><strong>Resource API</strong><p>Action-level authorization</p><em>Allowed read and denied production publish</em></div></div><div class="partner-architecture-takeaway"><span>THE POINT TO TEACH</span><strong>A successful sign-in proves a person. It does not prove a company relationship or authorize an API action.</strong><a class="outline" href="#evan/live">Run this architecture live →</a></div></section>`;}

function liveDemo(){return `<section class="external-live-stage"><header><div><span class="vendor-kicker">TWO LIVE SIDES · PARTNER API BOUNDARY</span><h2>Configure the relationship.<br><em>Prove the API decision.</em></h2><p>Follow Evan’s human sign-in into a separate registered integration, then show its app-only token and the API decision. Keep secrets and full tokens off the shared screen.</p></div><button class="primary" data-partner="desktop">Launch the two-sided stage →</button></header><ol class="partner-handoff" aria-label="From person to API decision"><li><b>01 · PERSON</b><strong>Evan signs in</strong><span>External ID user subject</span></li><li><b>02 · TRUST</b><strong>Partner verified</strong><span>Tidewater agreement</span></li><li><b>03 · APPLICATION</b><strong>Integration registered</strong><span>Client ID · secret kept private</span></li><li><b>04 · TOKEN</b><strong>App-only token</strong><span>Client credentials · approved permission</span></li><li><b>05 · API</b><strong>Allow or deny</strong><span>Actual response + correlated evidence</span></li></ol><div class="external-live-panes"><article><div class="live-pane-top"><span>ADMINISTRATOR</span><b>01</b></div><div class="live-pane-icon">ID</div><h3>External tenant</h3><p>Inspect Evan’s External ID sign-in, trusted partner mapping and the integration app registration.</p><ul><li>Confirm tenant and application</li><li>Verify Evan and Tidewater context</li><li>Locate the registered integration and client ID</li></ul><strong>Left side · protected admin desktop</strong></article><div class="external-live-link"><span>CONFIGURE</span><b>→</b><span>ENFORCE</span></div><article class="customer"><div class="live-pane-top"><span>PARTNER DEVELOPER</span><b>02</b></div><div class="live-pane-icon">ET</div><h3>Integration Exchange</h3><p>Sign in as Evan, inspect the registered integration, obtain its app-only token privately, then show one allowed sandbox call and one denied production action.</p><ul><li>Show the app/client ID, not its secret</li><li>Use an app-only token for a sandbox call</li><li>Show the real production denial</li></ul><strong>Right side · Integration Exchange link configured</strong></article></div><div class="external-live-run"><div><span>RECOMMENDED DEMO SEQUENCE</span><strong>Human sign-in → verified partner → integration registration → app-only token → sandbox allow → production deny → evidence + reset</strong></div><div><a class="outline" href="${e(vendorConfig.integrationPortalUrl)}" target="_blank" rel="noopener noreferrer">Open live Integration Exchange ↗</a><button class="outline" data-partner="desktop">Open admin + partner sessions ↗</button></div></div></section>`;}

function evidence(){return `<section class="partner-proof-board"><header><div><span class="vendor-kicker">EVAN’S PROOF BOARD</span><h2>One identity. Two API decisions. Evidence the room can follow.</h2><p>Start with the claim, show the record, and check it only after the audience sees the evidence.</p></div><div class="partner-proof-outcomes"><span><b>200</b> Sandbox read allowed</span><span class="deny"><b>403</b> Production publish denied</span></div></header><div class="partner-correlation"><span>CORRELATE ON</span><b>External ID subject</b><i>+</i><b>Application ID</b><i>+</i><b>UTC timestamp</b><i>+</i><b>Correlation ID</b></div><div class="partner-proof-grid">${proof.map(([title,source,description],index)=>`<label class="partner-proof-card"><input type="checkbox" data-partner-proof="${index}" ${checked.has(index)?'checked':''}><span class="proof-number">${String(index+1).padStart(2,'0')}</span><span class="proof-source">${e(source)}</span><strong>${e(title)}</strong><p>${e(description)}</p><em>${checked.has(index)?'SHOWN TO THE ROOM':'SHOW THIS LIVE'}</em></label>`).join('')}</div><div class="partner-proof-summary"><strong>${checked.size} / ${proof.length}</strong><span>evidence points shown</span><progress max="${proof.length}" value="${checked.size}"></progress></div><div class="partner-evidence-actions"><a class="outline" href="https://entra.microsoft.com/?tid=${e(vendorConfig.externalTenantId)}" target="_blank" rel="noopener noreferrer">Open external tenant ↗</a><a class="outline" href="${e(vendorConfig.integrationPortalUrl)}" target="_blank" rel="noopener noreferrer">Open Integration Exchange ↗</a><a class="primary" href="#evan/live">Open two-sided live demo →</a></div><section class="franchise-replay"><div><span class="vendor-kicker">RESET &amp; REPLAY</span><h3>End where you started.</h3><p>Remove the test production scope, restore the sandbox assignment, revoke the prepared session and run the denied action again. The restored 403 is the final proof.</p></div><div><span class="vendor-kicker">CLIENT QUESTION</span><blockquote>Could your team connect one customer sign-in to the exact business and API decision that followed?</blockquote></div></section></section>`;}

export function partnerPage(mode='experience'){
  view=['experience','architecture','live','ai','evidence'].includes(mode)?mode:'experience';
  const meta={experience:['THE STORY','Invite the partner. <em>Protect the API.</em>','Follow one external developer from branded registration to scoped API access and clean expiration.'],architecture:['ARCHITECTURE','Separate identity, trust and <em>technical authorization.</em>','Show where External ID ends, where partner context begins and where the API makes the decision.'],live:['LIVE DEMO','Show both sides. <em>Prove allow and deny.</em>','Place the external-tenant administrator beside Evan’s developer experience.'],ai:['HOW AI HELPS','Explain the API decision. <em>Change only with approval.</em>','Use AI to correlate sign-in, partner and API evidence before a narrow, reversible change.'],evidence:['EVIDENCE','Prove the person. <em>Prove the scope.</em>','Connect Evan’s sign-in to partner trust, consent, token claims and API enforcement.']}[view];
  const story=storyOpening({headline:'A developer joins the ecosystem.<br><em>He never becomes an employee.</em>',name:'Evan Torres',role:'Integration developer · Tidewater Channel Systems',portrait:'./assets/personas/evan-torres.webp',paragraphs:[
    'Evan works for Tidewater Channel Systems, an approved Harborline integration partner. An invitation takes him to the branded Integration Exchange, where he registers and signs in through Microsoft Entra External ID. Harborline knows who he is without creating a workforce employee account.',
    'His human sign-in does not establish that he represents Tidewater Channel Systems. The partner registry links Evan’s stable identity to a verified agreement, sponsor and effective dates. After reviewing the requested data use, he registers an integration in the Exchange. The registration creates a separate application identity with a client ID and a one-time client secret; the secret stays private.',
    'The integration, not Evan’s user session, exchanges its client credentials for an app-only token. The API checks that token and the current partner relationship before allowing a sandbox read or denying a production action. The room should compare the human sign-in, application registration, token and API decision as four distinct records. When the agreement ends, Harborline revokes the integration credentials and preserves the evidence.'
  ],truth:'External ID authenticates Evan; the Exchange registers his integration; the app-only token and resource API govern the integration’s actions.',question:'Where does your organization verify that a developer represents an approved partner before granting API scope?'});
  const ai=aiPage({kicker:'AI COPILOT · EVAN’S PARTNER API ACCESS',title:'Trace the denial. <em>Protect the production boundary.</em>',summary:'The private agent can compare Evan’s sign-in, the registered integration, its token and API results, then propose a correction for a presenter to review. This workshop makes no tenant change.',buttonAttr:'data-partner="desktop"',agent:{name:'Partner API Evidence Agent',status:'CONNECTED AGENT PATTERN',persona:'Evan Torres',portrait:'./assets/personas/evan-torres.webp',role:'Connect the human partner, registered integration, machine token and API decision in one reviewable chain.'},flow:[['Observe','Read the selected sign-in, token and API response.'],['Correlate','Match Evan’s subject to Tidewater Channel Systems and current scopes.'],['Propose','Draft the smallest time-bound scope correction.'],['Presenter applies','If approved and rehearsed, the administrator changes the integration permission in the real control plane.'],['Verify + restore','Re-run the API calls and restore the starting permission in the real control plane.']],inputs:['External ID sign-in and authentication details','Registered integration, app ID and granted permissions','App-only token claims, API request and authorization result'],outputs:['A cited explanation of the exact denial','A preview of the scope and expiration change','Before, after and restored API outcomes'],guardrail:'The agent can analyze and propose; it cannot execute from this public workshop. A human must approve and apply any rehearsed change, verify the real API result, then restore the baseline.'});
  const content=view==='experience'?story:view==='architecture'?architecture():view==='live'?liveDemo():view==='ai'?ai:evidence();
  return chapterFrame({classes:'partner-shell',accent:'#FF9A6B',glow:'#5a2413',topline:'MICROSOFT ENTRA EXTERNAL ID · PARTNER DEVELOPER JOURNEY',name:'EVAN TORRES',role:'INTEGRATION DEVELOPER',section:meta[0],title:meta[1],summary:meta[2],route:'evan',view,nav:[['experience','01','The story'],['live','02','Live demo'],['ai','03','How AI helps']],context:['EXTERNAL TENANT','Business customer','Partner verification','Scoped API authorization'],status:'PORTAL LINK AVAILABLE · SIGN-IN AND API PROOF PENDING',content,footer:'Evan · external tenant partner developer journey'});
}

export function installPartnerEvents(render,onDesktop){document.addEventListener('click',event=>{const button=event.target.closest('[data-partner]');if(!button)return;const action=button.dataset.partner;if(action==='desktop'){onDesktop();return;}if(action==='stage'){stageIndex=Number(button.dataset.index);if(view==='experience'&&stageIndex>1)location.hash='#evan/architecture';render();}});document.addEventListener('change',event=>{if(!event.target.matches('[data-partner-proof]'))return;const index=Number(event.target.dataset.partnerProof);event.target.checked?checked.add(index):checked.delete(index);render();document.querySelector(`[data-partner-proof="${index}"]`)?.focus();});}

export function evanGuide(){const step=(action,why,look)=>({action,why,look});return {name:'Evan Torres',time:'Partner developer journey',title:'Invite the partner. Protect the API.',job:'Integration developer',perspective:'Partner experience',liveUrl:vendorConfig.integrationPortalUrl,liveLabel:'Harborline Integration Exchange',liveKind:'partner application',story:'Evan signs in through External ID, is linked to Tidewater Channel Systems, registers an integration, and the integration receives only its approved API permission.',why:'Show that External ID authenticates the partner while the application preserves business trust, least privilege and clean expiration.',account:'Prepared Evan External ID test account',domain:'External tenant · verify in the administrator profile',cases:cases.filter(c=>[10,12,14,16,29,32,33,34].includes(c.id)),highlights:['Show Evan’s External ID sign-in','Verify partner and integration registration','Compare app token, allowed call and denied call'],admin:[step('Open the External ID tenant and inspect the Integration Exchange application and associated sign-up/sign-in user flow.','The partner experience must use the customer tenant and intended application registration.','Verify tenant, application ID, redirect URI, flow association, identity providers and collected attributes.'),step('Inspect the trusted partner mapping, registered integration, application ID, approved API products and agreement dates.','Self-asserted sign-up attributes cannot grant API authority.','Show the stable External ID subject, partner record, sponsor, effective dates and scope source.'),step('Correlate Evan’s human sign-in, integration registration, app-only token, allowed sandbox call and denied production call.','Authentication and API authorization are separate controls.','Keep the user subject and app/client ID distinct; match audience, application permission, time, resource and API decision.')],user:[step('Open the prepared Integration Exchange in Evan’s separate browser profile.','Keep the partner experience separate from the administrator session.','Use privately held credentials and the configured authentication method.'),step('Review the requested data use, then open the prepared integration registration and its granted API product.','The audience should see how a signed-in person sponsors a separate application identity.','Show the integration name, app/client ID and permission; keep its one-time secret and full access token private.'),step('Obtain the prepared app-only token and run the sandbox read, then attempt the prepared production action.','The token represents the integration, while the API decides whether this specific action is allowed.','Show the actual allow and deny results and correlate them with the app ID; show approval or step-up only if rehearsed.')],userTitle:'Experience Evan’s partner developer workspace',evidence:'Correlate External ID sign-in, trusted partner relationship, consent, token claims and the application/API decision.',caution:'The Integration Exchange link is configured. Verify Evan’s sign-in, partner mapping, allowed sandbox call, denied production call and reset path before each client session.',question:'Where does your application decide that this authenticated partner may perform this API action right now?'};}
